script:
(function () {
  'use strict';
  // Interest rate calculator: finds the rate implied by a loan amount L, n equal payments P made p times a
  // year, and an optional final lump sum (balloon) F paid with the last payment.
  //   Solve L = P * (1 - (1 + j)^-n) / j + F * (1 + j)^-n for the rate per payment j (bisection; the right
  //   side falls as j rises, so the root is unique). Annual rate (APR, nominal) = j * p;
  //   effective annual rate = (1 + j)^p - 1. If P*n + F equals L the rate is 0%; if less, it is negative.
  // Verified in Node (scratchpad w3loans/tests): $32,000 repaid at $960 a month for 3 years = 5.065%
  //   (matches a published calculator's default result); round trip: the payment on $25,000 at 7% for
  //   5 years ($495.03) solves back to 7.000%; $10,000 with 59 payments of $150 and a $3,000 balloon round
  //   trips to its rate; payments totalling exactly the loan give 0%; blank, negative, 0-term input and
  //   payments that total less than the loan show a message, never NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var rateFmt = new Intl.NumberFormat('en-US', { style: 'percent', minimumFractionDigits: 3, maximumFractionDigits: 3 });
  var NAMES = { 12: 'Monthly payment', 26: 'Payment every two weeks', 24: 'Twice-monthly payment', 52: 'Weekly payment',
                4: 'Quarterly payment', 1: 'Yearly payment' };

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function presentValue(P, F, j, n) {
    if (Math.abs(j) < 1e-12) return P * n + F;
    var d = Math.pow(1 + j, -n);
    return P * (1 - d) / j + F * d;
  }

  // Rate per period, or NaN when it is not positive and finite (callers check the totals first).
  function solveRate(L, P, F, n) {
    if (P * n + F <= L) return NaN;
    var lo = 0, hi = 1;
    while (presentValue(P, F, hi, n) > L && hi < 1e6) hi *= 2;
    for (var k = 0; k < 300; k++) {
      var mid = (lo + hi) / 2;
      if (presentValue(P, F, mid, n) > L) lo = mid; else hi = mid;
    }
    return (lo + hi) / 2;
  }

  function clearResults() {
    ['irApr', 'irEar', 'irPeriodic', 'irTotal', 'irInterest', 'irCount'].forEach(function (id) { setText(id, '–'); });
    el('irSens').textContent = '';
  }

  function cell(tr, text) { var td = document.createElement('td'); td.textContent = text; tr.appendChild(td); }

  function update() {
    var amount = read('irAmount'), years = read('irYears', true), months = read('irMonths', true), pay = read('irPay'),
        balloon = read('irBalloon', true), perYear = parseInt(el('irFreq').value, 10), msg = '';
    var termMonths = years * 12 + months;
    var n = Math.round(termMonths * perYear / 12);
    setText('irPayLabel', NAMES[perYear] || 'Payment');
    if (isNaN(amount) || amount <= 0) msg = 'Enter a loan amount greater than $0.';
    else if (isNaN(years) || isNaN(months) || years < 0 || months < 0 || years % 1 !== 0 || months % 1 !== 0 || years > 50 || months > 11)
      msg = 'Enter the term as whole years (0 to 50) and months (0 to 11).';
    else if (termMonths < 1) msg = 'Enter a loan term of at least one month.';
    else if (n < 1) msg = 'The term is shorter than one payment period. Lengthen the term or pay more often.';
    else if (isNaN(pay) || pay <= 0) msg = 'Enter a payment greater than $0.';
    else if (isNaN(balloon) || balloon < 0) msg = 'The final lump sum cannot be negative.';
    else if (pay * n + balloon < amount - 0.005)
      msg = 'Your payments add up to ' + money.format(pay * n + balloon) + ', less than the ' + money.format(amount) +
            ' borrowed, so there is no positive interest rate. Check the payment and term.';
    var j = 0;
    if (!msg && pay * n + balloon > amount + 0.005) {
      j = solveRate(amount, pay, balloon, n);
      if (!isFinite(j) || j * perYear > 10) msg = 'Those figures imply an annual rate above 1,000%. Check the payment and term.';
    }
    var error = el('irError');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var total = pay * n + balloon;
    setText('irApr', rateFmt.format(j * perYear));
    setText('irEar', rateFmt.format(Math.pow(1 + j, perYear) - 1));
    setText('irPeriodic', rateFmt.format(j));
    setText('irTotal', money.format(total));
    setText('irInterest', money.format(Math.max(0, total - amount)));
    setText('irCount', String(n) + (balloon > 0 ? ' + final lump sum' : ''));

    var body = el('irSens');
    body.textContent = '';
    [-0.1, -0.05, 0, 0.05, 0.1].forEach(function (f) {
      var p = Math.round(pay * (1 + f) * 100) / 100, tr = document.createElement('tr');
      cell(tr, money.format(p) + (f === 0 ? ' (yours)' : ''));
      var t = p * n + balloon;
      if (t < amount - 0.005) cell(tr, 'Below 0%');
      else if (t <= amount + 0.005) cell(tr, rateFmt.format(0));
      else { var r = solveRate(amount, p, balloon, n); cell(tr, isFinite(r) && r * perYear <= 10 ? rateFmt.format(r * perYear) : 'Over 1,000%'); }
      cell(tr, money.format(Math.max(0, t - amount)));
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('irForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
